@php
    $assistantUser = auth()->user();
    $assistantVisible = $assistantUser instanceof \App\Models\User
        && app(\App\Services\AiAssistant\AiAssistantAuthorization::class)->allows($assistantUser, \App\Enums\AiAssistantPermission::Use)
        && app(\App\Services\AiAssistant\AiAssistantSettings::class)->enabled();
@endphp
@if ($assistantVisible)
<div x-data="tpzAssistant()" x-init="init()" class="tpz-ai-root" wire:ignore>
    <button x-show="!open" @click="open=true; load()" class="tpz-ai-launcher" aria-label="Open TPZ AI Assistant"><span>✦</span><span>TPZ AI</span></button>
    <section x-cloak x-show="open" :class="{'tpz-ai-full':full}" class="tpz-ai-panel" role="dialog" aria-label="TPZ AI Assistant">
        <header class="tpz-ai-header"><div><strong>✦ TPZ AI</strong><small x-text="provider === 'mock' ? 'Demo mode · ERP data' : (available ? 'ERP data · Read only' : 'OpenAI unavailable · API key not configured')"></small></div><div class="tpz-ai-controls"><button @click="newChat()" title="New chat">＋</button><button @click="full=!full" title="Expand or restore">□</button><button @click="open=false" title="Minimize">−</button><button @click="open=false;full=false;conversationId=null;messages=[]" title="Close">×</button></div></header>
        <div class="tpz-ai-toolbar"><span>Conversations</span><button @click="newChat()">New chat</button></div>
        <div class="tpz-ai-layout" :class="{'tpz-ai-expanded':full}">
            <aside class="tpz-ai-history"><template x-for="item in conversations" :key="item.id"><div class="tpz-ai-history-row"><button @click="select(item.id)" :class="{'active':item.id===conversationId}" x-text="item.title"></button><button class="tpz-ai-delete" @click="deleteChat(item.id)" title="Delete conversation" aria-label="Delete conversation">×</button></div></template></aside>
            <div class="tpz-ai-main"><div class="tpz-ai-messages" x-ref="messages">
                <template x-if="messages.length===0"><div class="tpz-ai-welcome"><div class="sparkle">✦</div><strong>Ask TPZ about your ERP</strong><p>Answers use only data you are authorized to see.</p><div class="tpz-ai-suggestions"><button @click="suggest('What were today’s sales orders?')">Today’s sales orders</button><button @click="suggest('Show current inventory')">Current inventory</button><button @click="suggest('Which customer returns are pending?')">Pending returns</button><button @click="suggest('Show pending stock requests')">Stock Requests</button></div></div></template>
                <template x-for="message in messages" :key="message.id || message.localId"><article :class="message.role==='user'?'user':'assistant'" class="tpz-ai-bubble"><div x-text="message.content"></div><template x-if="message.role==='assistant' && message.status==='complete'"><button class="tpz-ai-copy" @click="copy(message.content)">Copy</button></template><template x-if="message.status==='failed'"><button class="tpz-ai-copy" @click="retry()">Retry</button></template></article></template>
                <div x-show="busy" class="tpz-ai-typing"><i></i><i></i><i></i></div><div x-show="error" class="tpz-ai-error" x-text="error"></div>
            </div><form class="tpz-ai-composer" @submit.prevent="send()"><textarea x-ref="input" x-model="draft" @keydown.enter.prevent="if(!$event.shiftKey) send()" placeholder="Ask about sales, inventory, returns…" rows="1" maxlength="6000"></textarea><button type="submit" :disabled="busy || !draft.trim()">➤</button></form><small class="tpz-ai-foot">Read-only · ERP permissions apply · Verify important figures</small></div>
        </div>
    </section>
</div>
<script>
function tpzAssistant(){return {open:false,full:false,busy:false,error:'',draft:'',provider:'mock',available:true,conversationId:null,conversations:[],messages:[],lastPrompt:'',init(){},async load(){try{const r=await fetch('/admin/ai-assistant',{headers:{Accept:'application/json'}});if(!r.ok)throw Error();const d=await r.json();this.conversations=d.conversations;this.provider=d.settings.provider;this.available=d.settings.available;if(!this.available)this.error='OpenAI is unavailable because the server API key is not configured.';if(!this.conversationId&&this.conversations.length)await this.select(this.conversations[0].id);else if(!this.conversationId){await this.newChat();await this.list()}}catch(e){this.error='Assistant is unavailable. Please refresh or try again.'}},headers(){return {Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]')?.content||''}},async list(){const r=await fetch('/admin/ai-assistant',{headers:{Accept:'application/json'}});if(r.ok)this.conversations=(await r.json()).conversations},async newChat(){const r=await fetch('/admin/ai-assistant/conversations',{method:'POST',headers:this.headers()});if(!r.ok){this.error='Could not start a new chat.';return}this.conversationId=(await r.json()).conversation.id;this.messages=[];this.error=this.available?'':'OpenAI is unavailable because the server API key is not configured.';await this.list();this.$nextTick(()=>this.$refs.input?.focus())},async deleteChat(id){if(!confirm('Delete this conversation and its messages?'))return;const r=await fetch('/admin/ai-assistant/conversations/'+id,{method:'DELETE',headers:this.headers()});if(!r.ok){this.error='Could not delete the conversation.';return}if(this.conversationId===id){this.conversationId=null;this.messages=[]}await this.list()},async select(id){this.conversationId=id;this.error=this.available?'':'OpenAI is unavailable because the server API key is not configured.';const r=await fetch('/admin/ai-assistant/conversations/'+id,{headers:{Accept:'application/json'}});if(!r.ok){this.error='Conversation could not be loaded.';return}this.messages=(await r.json()).messages;this.scroll()},async suggest(text){this.draft=text;await this.send()},async send(retry=false){if(this.busy)return;if(!retry){this.lastPrompt=this.draft.trim();if(!this.lastPrompt)return;this.messages.push({role:'user',content:this.lastPrompt,localId:Date.now()});this.draft=''}this.error='';const item={role:'assistant',content:'',status:'streaming',localId:Date.now()+1};this.messages.push(item);this.busy=true;this.scroll();try{const response=await fetch('/admin/ai-assistant/conversations/'+this.conversationId+'/messages',{method:'POST',headers:this.headers(),body:JSON.stringify({message:this.lastPrompt})});if(!response.ok)throw Error();const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const parts=buffer.split('\n\n');buffer=parts.pop();for(const part of parts){const line=part.split('\n').find(x=>x.startsWith('data: '));if(!line)continue;const event=JSON.parse(line.slice(6));if(event.type==='delta'){item.content+=event.text;this.scroll()}if(event.type==='done'){item.status='complete';item.id=event.message_id}if(event.type==='error'){this.error=event.message;throw Error()}}}if(item.status==='streaming')throw Error();await this.list()}catch(e){item.status='failed';if(!this.error)this.error='The response was interrupted. Retry when ready.'}finally{this.busy=false;this.scroll()}},async retry(){const last=this.messages.at(-1);if(last?.role==='assistant'&&last.status==='failed'){this.messages.pop();await this.send(true)}},async copy(text){try{await navigator.clipboard.writeText(text)}catch(e){this.error='Could not copy this response.'}},scroll(){this.$nextTick(()=>{const el=this.$refs.messages;if(el)el.scrollTop=el.scrollHeight})}}}
</script>
@endif
